package com.bank.lld;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class LldDemo {
    private static final Logger log = Logger.getLogger("LLD");

    public static void main(String[] args) {
        Account rajesh = AccountFactory.create("SAV2001", "Rajesh", new BigDecimal("1000000"), "SAVINGS");
        Account priya  = AccountFactory.create("CUR3001", "Priya",  new BigDecimal("250000"),  "CURRENT");
        TransferService service = new TransferService();
        service.transfer(rajesh, priya, new BigDecimal("50000"));
        log.info(() -> "Rajesh=" + rajesh.getBalance() + " Priya=" + priya.getBalance());
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String accountId; private final String holderName;
    private BigDecimal balance; private final String type;
    Account(String id, String name, BigDecimal bal, String type) {
        this.accountId = id; this.holderName = name; this.balance = bal; this.type = type;
    }
    void debit(BigDecimal amt) {
        if (balance.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amt);
    }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
    BigDecimal getBalance() { return balance; }
    String getAccountId() { return accountId; }
}

// ─── Would be in factory/AccountFactory.java ───
class AccountFactory {
    static Account create(String id, String name, BigDecimal bal, String type) {
        return new Account(id, name, bal, type); // step 5: centralised creation
    }
}

// ─── Would be in service/TransferService.java ───
class TransferService {
    void transfer(Account from, Account to, BigDecimal amount) {
        from.debit(amount);   // step 4: behaviour
        to.credit(amount);    // step 6: atomic intent
    }
}
